   <div className="stat-grid">{[{label:'Active coachees',value:scopedClients.filter(c=>c.status==='Active').length,Icon:Users,note:'Current coaching journeys'},{label:'Sessions this month',value:data.sessions.filter(s=>scopedIds.has(s.clientId)&&s.status==='Completed'&&s.date.startsWith(today().slice(0,7))).length,Icon:NotebookPen,note:monthLabel(today().slice(0,7))},{label:'Notes to review',value:pending.length,Icon:BookOpen,note:'Completed sessions awaiting review'},{label:'Open commitments',value:openActions.length,Icon:CheckSquare,note:overdue.length?`${overdue.length} overdue`:'Actions and assignments'}].map(x=><div className="stat" key={x.label}><div><span>{x.label}</span><x.Icon size={18}/></div><strong>{x.value}</strong><small>{x.note}</small></div>)}</div>
   {!data.clients.length?<div className="welcome-grid"><section className="welcome"><span className="pill">YOUR FIRST COACHING JOURNEY</span><h2>Give your notes<br/>a place to come together.</h2><p>Start with one coachee. Bring in a session, record what matters and carry the agreed actions forward.</p><Button kind="primary" onClick={()=>setEditor({kind:'client',item:blankClient()})}>Add your first coachee<ArrowUpRight size={17}/></Button><button className="text-button" onClick={()=>void demo()} disabled={busy}>Or explore with a fictional example</button><div className="welcome-decoration" aria-hidden="true"><div className="orb one"/><div className="orb two"/><span><NotebookPen size={46}/></span></div></section><section className="card start-guide"><h3>A lighter reporting routine</h3>{[['01','Bring in the session','Paste notes or a transcript from Granola or Fireflies.'],['02','Record the evidence','Keep the coachee account, your intervention and their response.'],['03','Prepare the report','Approve a short organisational summary for the monthly draft.']].map(x=><div className="step" key={x[0]}><b>{x[0]}</b><div><h4>{x[1]}</h4><p>{x[2]}</p></div></div>)}<div className="quiet-note"><Lock size={15}/>Your private reflections stay in the session record.</div></section></div>:<div className="two-col"><section className="card"><div className="card-heading"><h3>Coachees at a glance</h3><button className="text-button" onClick={()=>navigate('Coachees')}>View all<ArrowUpRight size={15}/></button></div>{data.clients.filter(c=>c.status==='Active').slice(0,6).map(c=><button className="person-row" key={c.id} onClick={()=>{navigate('Coachees');setSelected(c.id);}}><Avatar name={c.name}/><span><strong>{c.name}</strong><small>{c.role||c.company||'Coaching programme'}</small></span><Badge>{data.sessions.filter(s=>s.clientId===c.id&&s.status==='Completed').length} sessions</Badge><ChevronRight size={17}/></button>)}{!data.clients.some(c=>c.status==='Active')&&<p className="muted">No active journeys. Update a coachee’s status to get started.</p>}</section><section className="card"><div className="card-heading"><h3>Needs your attention</h3><Clock size={18}/></div>{pending.slice(0,3).map(s=><button key={s.id} className="attention-row" onClick={()=>setEditor({kind:'session',item:s})}><span className="icon-square"><NotebookPen size={18}/></span><span><strong>Review {client(s.clientId)?.name}’s notes</strong><small>Session {s.number} · {fmt(s.date)}</small></span><ChevronRight size={16}/></button>)}{overdue.slice(0,3).map(a=><button key={a.id} className="attention-row" onClick={()=>setEditor({kind:'action',item:a})}><span className="icon-square peach"><CheckSquare size={18}/></span><span><strong>{a.title}</strong><small>{client(a.clientId)?.name} · Due {fmt(a.dueDate)}</small></span></button>)}{!pending.length&&!overdue.length&&<Empty title="You’re up to date" text="There are no overdue commitments or session notes awaiting review."/>}</section></div>}
